// Normalise whatever the form sends into a clean lead object.
// Works with JSON bodies and standard form posts.
// Extend the pick() lists below to match your form's field names.
const body = $json.body || $json;
const pick = (...keys) => {
  for (const k of keys) {
    const v = body[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

const lead = {
  lead_name: pick('name', 'full_name', 'fullName', 'first_name', 'Name') || 'Unknown',
  lead_email: pick('email', 'email_address', 'emailAddress', 'Email'),
  lead_phone: pick('phone', 'phone_number', 'tel', 'mobile', 'Phone'),
  lead_company: pick('company', 'company_name', 'business', 'organisation', 'Company'),
  lead_message: pick('message', 'enquiry', 'inquiry', 'details', 'project', 'description', 'Message'),
  lead_budget: pick('budget', 'budget_range', 'Budget'),
  lead_source: pick('source', 'utm_source', 'referrer') || 'website form',
  received_at: new Date().toISOString()
};

// Minimum bar to process: a real-looking email address.
lead.valid = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(lead.lead_email);

return [{ json: lead }];

