// Safely parse the model's JSON verdict. If anything is off, fall back to a
// conservative "review manually" verdict so the lead is never lost.
const src = $('Normalize Enquiry').first().json;
let raw = '';
try { raw = $json.choices[0].message.content || ''; } catch (e) { raw = ''; }

let verdict = {
  score: 0,
  tier: 'cold',
  budget_signal: 'unknown',
  intent: 'none',
  fit_reason: 'AI response missing or unparseable - review this lead manually.',
  summary: (src.lead_message || '').slice(0, 200),
  reply_draft: ''
};

try {
  const cleaned = raw.replace(/```json|```/gi, '').trim();
  const parsed = JSON.parse(cleaned);
  if (parsed && typeof parsed === 'object') verdict = { ...verdict, ...parsed };
} catch (e) {
  // keep the conservative fallback
}

verdict.score = Math.max(0, Math.min(100, Math.round(Number(verdict.score) || 0)));
if (!['hot', 'warm', 'cold'].includes(verdict.tier)) {
  verdict.tier = verdict.score >= 70 ? 'hot' : verdict.score >= 40 ? 'warm' : 'cold';
}

return [{ json: { ...src, ...verdict, qualified: verdict.tier === 'hot' || verdict.tier === 'warm' } }];

// ---- Edit these to match your business ----
const SLOT_MINUTES = 30;   // meeting length
const DAY_START_HOUR = 9;  // first bookable hour (24h clock, instance timezone)
const DAY_END_HOUR = 17;   // no meeting may end after this hour
const DAYS_AHEAD = 5;      // how many days forward to search
// -------------------------------------------

// Collect busy windows from the calendar events we just fetched.
const busy = [];
for (const item of $input.all()) {
  const ev = item.json || {};
  if (!ev.start) continue;
  const s = new Date(ev.start.dateTime || ev.start.date);
  const e = new Date(ev.end && (ev.end.dateTime || ev.end.date));
  if (!isNaN(s) && !isNaN(e)) busy.push([s.getTime(), e.getTime()]);
}

const now = new Date();
let slot = null;
for (let d = 1; d <= DAYS_AHEAD && !slot; d++) {
  const day = new Date(now);
  day.setDate(day.getDate() + d);
  const dow = day.getDay();
  if (dow === 0 || dow === 6) continue; // skip weekends
  const dayEnd = new Date(day);
  dayEnd.setHours(DAY_END_HOUR, 0, 0, 0);
  for (let h = DAY_START_HOUR; h < DAY_END_HOUR && !slot; h++) {
    for (const m of [0, 30]) {
      const start = new Date(day);
      start.setHours(h, m, 0, 0);
      const end = new Date(start.getTime() + SLOT_MINUTES * 60000);
      if (end > dayEnd) continue;
      const clash = busy.some(([bs, be]) => start.getTime() < be && end.getTime() > bs);
      if (!clash) { slot = { start, end }; break; }
    }
  }
}

const lead = $('Parse AI Verdict').first().json;
if (!slot) {
  // Calendar is slammed - flag for manual booking; the lead still gets logged and emailed.
  return [{ json: { ...lead, slot_found: false, slot_start: '', slot_end: '' } }];
}
return [{ json: { ...lead, slot_found: true, slot_start: slot.start.toISOString(), slot_end: slot.end.toISOString() } }];

