// Runs on BOTH paths: after a booking attempt (hot/warm) or straight from the cold branch.
const v = $('Parse AI Verdict').first().json; // always available on both paths
let booked = false;
let meetingStart = '';
let meetingLink = '';
try {
  const ev = $('Book Appointment').first().json;
  if (ev && ev.id && ev.start) {
    booked = true;
    meetingStart = ev.start.dateTime || ev.start.date || '';
    meetingLink = ev.htmlLink || '';
  }
} catch (e) {
  // Cold-lead path (booking node never ran) or booking failed - handled below.
}

const booking_status = booked
  ? 'Booked'
  : (v.qualified ? 'NEEDS MANUAL BOOKING' : 'Not booked (cold lead)');

return [{ json: { ...v, booked, booking_status, meeting_start: meetingStart, meeting_link: meetingLink } }];
